Here is the commit message:
fuse: limit FUSE_NOTIFY_RETRIEVE to uptodate folios

FUSE_NOTIFY_RETRIEVE must be limited to uptodate folios; !uptodate folios
can contain uninitialized data.
Since FUSE_NOTIFY_RETRIEVE is intended to only return data that is already
in the page cache and not wait for data from the FUSE daemon, treat
!uptodate folios as if they weren't present.

This only has security impact on systems that don't enable automatic
zero-initialization of all page allocations via
CONFIG_INIT_ON_ALLOC_DEFAULT_ON or init_on_alloc=1.

Cc: stable@kernel.org
Fixes: 2d45ba381a74 ("fuse: add retrieve request")
Signed-off-by: Jann Horn <jannh@google.com>
Link: https://patch.msgid.link/20260519-fuse-retrieve-uptodate-v1-1-a7a1912a37f9@google.com
Acked-by: Miklos Szeredi <mszeredi@redhat.com>
Signed-off-by: Christian Brauner (Amutable) <brauner@kernel.org>

Here is the root cause:
The fuse_retrieve function in fs/fuse/dev.c did not verify that a folio is marked as uptodate before returning its data in response to a FUSE_NOTIFY_RETRIEVE request. This allowed retrieval of uninitialized data from folios that are not yet fully populated, potentially leaking sensitive information on systems without automatic zero-initialization.

Here is the patch:

 static int fuse_retrieve(struct fuse_mount *fm, struct inode *inode,
 			 struct fuse_notify_retrieve_out *outarg)
 {
 	int err;
 	struct address_space *mapping = inode->i_mapping;
 	loff_t file_size;
 	unsigned int num;
 	unsigned int offset;
 	size_t total_len = 0;
 	unsigned int num_pages;
 	struct fuse_conn *fc = fm->fc;
 	struct fuse_retrieve_args *ra;
 	size_t args_size = sizeof(*ra);
 	struct fuse_args_pages *ap;
 	struct fuse_args *args;
 	loff_t pos = outarg->offset;

 	offset = offset_in_page(pos);
 	file_size = i_size_read(inode);

 	num = min(outarg->size, fc->max_write);
 	if (pos > file_size)
 		num = 0;
 	else if (num > file_size - pos)
 		num = file_size - pos;

 	num_pages = DIV_ROUND_UP(num + offset, PAGE_SIZE);
 	num_pages = min(num_pages, fc->max_pages);
 	num = min(num, num_pages << PAGE_SHIFT);

 	args_size += num_pages * (sizeof(ap->folios[0]) + sizeof(ap->descs[0]));

 	ra = kzalloc(args_size, GFP_KERNEL);
 	if (!ra)
 		return -ENOMEM;

 	ap = &ra->ap;
 	ap->folios = (void *) (ra + 1);
 	ap->descs = (void *) (ap->folios + num_pages);

 	args = &ap->args;
 	args->nodeid = outarg->nodeid;
 	args->opcode = FUSE_NOTIFY_REPLY;
 	args->in_numargs = 3;
 	args->in_pages = true;
 	args->end = fuse_retrieve_end;

 	while (num && ap->num_folios < num_pages) {
 		struct folio *folio;
 		unsigned int folio_offset;
 		unsigned int nr_bytes;
 		pgoff_t index = pos >> PAGE_SHIFT;

 		folio = filemap_get_folio(mapping, index);
 		if (IS_ERR(folio))
 			break;
+		if (!folio_test_uptodate(folio)) {
+			folio_put(folio);
+			break;
+		}

 		folio_offset = offset_in_folio(folio, pos);
 		nr_bytes = min(folio_size(folio) - folio_offset, num);

 		ap->folios[ap->num_folios] = folio;
 		ap->descs[ap->num_folios].offset = folio_offset;
 		ap->descs[ap->num_folios].length = nr_bytes;
 		ap->num_folios++;

 		pos += nr_bytes;
 		num -= nr_bytes;
 		total_len += nr_bytes;
 	}
 	ra->inarg.offset = outarg->offset;
 	ra->inarg.size = total_len;
 	fuse_set_zero_arg0(args);
 	args->in_args[1].size = sizeof(ra->inarg);
 	args->in_args[1].value = &ra->inarg;
 	args->in_args[2].size = total_len;

 	err = fuse_simple_notify_reply(fm, args, outarg->notify_unique);
 	if (err)
 		fuse_retrieve_end(fm, args, err);

 	return err;
 }



